This Terraform configuration creates a small AWS networking setup suitable for an example Amazon Neptune deployment. It defines:

- An AWS provider in `us-east-1`
- A dedicated VPC
- Two example private subnets in different Availability Zones
- An Amazon Neptune subnet group that includes both subnets

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the Neptune subnet group resources into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the example VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_one_cidr_block" {
  description = "CIDR block for the first Neptune subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_two_cidr_block" {
  description = "CIDR block for the second Neptune subnet."
  type        = string
  default     = "10.0.2.0/24"
}

